Function grande <- Mayor(a As Integer, b As Integer)
  Define grande As Integer <- a;
  If b > a Then
    grande <- b;
  EndIf
EndFunction

Function acumulado <- Reducir(v As Vector<Integer>, f As Function(Integer, Integer) As Integer, inicial As Integer)
  Define acumulado As Integer <- inicial;
  For Each elemento In v Do
    acumulado <- f(acumulado, elemento);
  EndFor
EndFunction

Algorithm Maximo
  Define numeros As Vector<Integer> <- vector();
  Define numero As Integer;
  Read numero;
  While numero <> 0 Do
    numeros.append(numero);
    Read numero;
  EndWhile
  If numeros.length() = 0 Then
    Write "Sin números";
  Else
    Write Reducir(numeros, Mayor, numeros[0]);
  EndIf
EndAlgorithm
